@startuml

class Gym {
  + ComputeMonthlyBalance(d : date) : int
  + ComputeAnnualBalance(d : date) : int
  + SendArrearsReminders()
  + SendMedicalCheckReminders()
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + baseCost : int
}

class MonthlySubscription extends Subscription {
}

class AnnualSubscription extends Subscription {
}

class Service {
  + name : string
  + additionalFee : int
}

class WorkoutPlan {
  + visitsPerWeek : int
}

class WorkoutPlanExercise {
  + exerciseName : string
  + repetitions : int
  + frequency : string
}

class MedicalCheck {
  + date : date
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
}

Gym "1" -- "*" Customer : manages
Gym "1" -- "*" Subscription : offers
Gym "1" -- "*" Service : offers
Gym "1" -- "*" MedicalStaff : employs
Customer "1" -- "1" Subscription : has
Customer "1" -- "0..1" WorkoutPlan : is associated with
Customer "1" -- "0..*" MedicalCheck : undergoes
MedicalStaff "1" -- "*" MedicalCheck : performs
MedicalStaff "1" -- "*" Customer : assists
WorkoutPlan "1" *-- "1..*" WorkoutPlanExercise : defines
Subscription "1" -- "*" Service : includes

@enduml

